<div class="table-wrap"><table><thead><tr><th>Empréstimo / pessoa</th><th>Equipamento</th><th>Saída</th><th>Tempo</th><th>Situação</th><th>Ações</th></tr></thead><tbody>
<?php foreach($rows as $r): ?><tr><td><strong><?= e($r['nome']) ?></strong><small>#<?= e($r['id']) ?> · <?= e($r['departamento']) ?></small></td><td><?= e($r['tipo'].' '.$r['marca'].' '.$r['modelo']) ?><small><?= e($r['id_ativo']) ?></small></td><td><?= dateBr($r['data_saida']) ?></td><td><?= e($r['dias']) ?> dias</td><td><span class="badge <?= $r['data_devolucao']?'green':'amber' ?>"><?= $r['data_devolucao']?'Devolvido':'Em aberto' ?></span><?php if($r['data_devolucao']): ?><small><?= dateBr($r['data_devolucao']) ?></small><?php endif ?></td><td><div class="stack"><a href="<?= e(url('term',['id'=>$r['id']])) ?>">Termo de responsabilidade</a><?php if(!$r['data_devolucao']): ?><a href="<?= e(url('return-form',['id'=>$r['id']])) ?>">Registrar devolução →</a><?php else: ?><a href="<?= e(url('term',['id'=>$r['id'],'kind'=>'return'])) ?>">Termo de devolução</a><?php endif ?></div></td></tr><?php endforeach ?>
<?php if(!$rows): ?><tr><td colspan="6" class="empty">Nenhum empréstimo encontrado.</td></tr><?php endif ?></tbody></table></div>
